def zugang_uebernehmen(apps, schema_editor):
    """Die bisher gemeinsamen Zugangsdaten werden persönlich (ADR 0129). Sie gehen an das eine
    aktive Konto, dessen E-Mail der Anmeldung im Vereinsportal entspricht – nur dann ist klar,
    wem sie gehören. Sonst entfallen sie und werden neu eingetragen; niemand soll die Anmeldung
    einer anderen Person erben."""
    einstellungen = apps.get_model("vereinsportal", "PortalEinstellungen").objects.first()
    if not einstellungen or not (einstellungen.email and einstellungen.passwort_verschluesselt):
        return
    Benutzer = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    konten = list(Benutzer.objects.filter(email__iexact=einstellungen.email, is_active=True)[:2])
    if len(konten) == 1:
        apps.get_model("vereinsportal", "Zugang").objects.create(
            benutzer=konten[0], email=einstellungen.email,
            passwort_verschluesselt=einstellungen.passwort_verschluesselt,
        )


